    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (P, P + 80); (IN, IN + 8)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' P (ParserCoreCells (mkPC (pc_blim_has c1) (pc_blim c1) (pc_len c1) (pc_len0 c1) (pc_skip c1) (pc_hlim c1) 2 (pc_f c1)) pad7 pad2)
    /\ rw_cells bsegs m' IN [C8 (wz itv)]
